"use client";

import { type JSX, useState } from "react";
import { useTranslation } from "react-i18next";
import { Webhook } from "@formbricks/database/prisma-browser";
import { TSurvey } from "@formbricks/types/surveys/types";
import { WebhookModal } from "@/modules/integrations/webhooks/components/webhook-detail-modal";
import { EmptyState } from "@/modules/ui/components/empty-state";

interface WebhookTableProps {
  workspaceId: string;
  webhooks: Webhook[];
  surveys: TSurvey[];
  children: [JSX.Element, JSX.Element[]];
  isReadOnly: boolean;
  allowInternalUrls: boolean;
  surveyVisibilityEnabled: boolean;
}

export const WebhookTable = ({
  workspaceId,
  webhooks,
  surveys,
  children: [TableHeading, webhookRows],
  isReadOnly,
  allowInternalUrls,
  surveyVisibilityEnabled,
}: Readonly<WebhookTableProps>) => {
  const [isWebhookDetailModalOpen, setWebhookDetailModalOpen] = useState(false);
  const { t } = useTranslation();
  const [activeWebhook, setActiveWebhook] = useState<Webhook>({
    workspaceId,
    id: "",
    name: "",
    url: "",
    source: "user",
    triggers: [],
    surveyIds: [],
    createdAt: new Date(),
    updatedAt: new Date(),
    secret: null,
  });

  const handleOpenWebhookDetailModalClick = (e: React.MouseEvent, webhook: Webhook) => {
    e.preventDefault();
    setActiveWebhook(webhook);
    setWebhookDetailModalOpen(true);
  };

  return (
    <>
      {webhooks.length === 0 ? (
        <EmptyState text={t("workspace.integrations.webhooks.empty_webhook_message")} />
      ) : (
        <div className="rounded-lg border border-slate-200">
          {TableHeading}
          <div className="grid-cols-7">
            {webhooks.map((webhook, index) => (
              <button
                type="button"
                onClick={(e) => {
                  handleOpenWebhookDetailModalClick(e, webhook);
                }}
                className="w-full"
                key={webhook.id}>
                {webhookRows[index]}
              </button>
            ))}
          </div>
        </div>
      )}
      <WebhookModal
        open={isWebhookDetailModalOpen}
        setOpen={setWebhookDetailModalOpen}
        webhook={activeWebhook}
        surveys={surveys}
        isReadOnly={isReadOnly}
        allowInternalUrls={allowInternalUrls}
        surveyVisibilityEnabled={surveyVisibilityEnabled}
      />
    </>
  );
};

import { z } from "zod";
import { ZWebhook } from "@formbricks/database/zod/webhooks";

export const ZWebhookInput = ZWebhook.partial({
  name: true,
  source: true,
  surveyIds: true,
}).pick({
  name: true,
  source: true,
  surveyIds: true,
  triggers: true,
  url: true,
});

export type TWebhookInput = z.infer<typeof ZWebhookInput>;

"use client";

import { TFunction } from "i18next";
import { useTranslation } from "react-i18next";
import { Webhook } from "@formbricks/database/prisma-browser";
import { TSurvey } from "@formbricks/types/surveys/types";
import { timeSince } from "@/lib/time";
import { RestrictedSurveyHint } from "@/modules/survey/visibility/components/restricted-survey-hint";
import { hasRestrictedAttachedSurvey } from "@/modules/survey/visibility/lib/outbound";
import { Badge } from "@/modules/ui/components/badge";

const renderSelectedSurveysText = (webhook: Webhook, allSurveys: TSurvey[]) => {
  let surveyNames: string[];

  if (webhook.surveyIds.length === 0) {
    surveyNames = allSurveys.map((survey) => survey.name);
  } else {
    surveyNames = webhook.surveyIds
      .map((surveyId) => {
        const survey = allSurveys.find((s) => s.id === surveyId);
        return survey ? survey.name : "";
      })
      .filter(Boolean);
  }

  if (surveyNames.length === 0) {
    return <p className="text-slate-400">-</p>;
  }

  return (
    <p className="truncate text-slate-400" title={surveyNames.join(", ")}>
      {surveyNames.join(", ")}
    </p>
  );
};

const renderSelectedTriggersText = (webhook: Webhook, t: TFunction) => {
  if (webhook.triggers.length === 0) {
    return <p className="text-slate-400">{t("workspace.integrations.webhooks.no_triggers")}</p>;
  } else {
    let cleanedTriggers = webhook.triggers.map((trigger) => {
      if (trigger === "responseCreated") {
        return t("workspace.integrations.webhooks.response_created");
      } else if (trigger === "responseUpdated") {
        return t("workspace.integrations.webhooks.response_updated");
      } else if (trigger === "responseFinished") {
        return t("workspace.integrations.webhooks.response_finished");
      } else {
        return trigger;
      }
    });

    return (
      <p className="text-slate-400">
        {cleanedTriggers
          .sort((a, b) => {
            const triggerOrder = {
              "Response Created": 1,
              "Response Updated": 2,
              "Response Finished": 3,
            };

            return (triggerOrder as Record<string, number>)[a] - (triggerOrder as Record<string, number>)[b];
          })
          .join(", ")}
      </p>
    );
  }
};

export const WebhookRowData = ({
  webhook,
  surveys,
  surveyVisibilityEnabled,
}: Readonly<{ webhook: Webhook; surveys: TSurvey[]; surveyVisibilityEnabled: boolean }>) => {
  const { t, i18n } = useTranslation();
  const locale = i18n.resolvedLanguage ?? i18n.language ?? "en-US";

  return (
    <div className="mt-2 grid h-auto grid-cols-12 content-center rounded-lg py-2 hover:bg-slate-100">
      <div className="col-span-3 flex items-center truncate pl-6 text-sm">
        <div className="flex items-center">
          <div className="text-left">
            {webhook.name ? (
              <div className="text-left">
                <div className="font-medium text-slate-900">{webhook.name}</div>
                <div className="text-xs text-slate-400">{webhook.url}</div>
              </div>
            ) : (
              <div className="font-medium text-slate-900">{webhook.url}</div>
            )}
          </div>
        </div>
      </div>
      <div className="col-span-1 my-auto text-center text-sm text-slate-800">
        <Badge type="gray" size="tiny" text={webhook.source || t("common.user")} className="capitalize" />
      </div>
      <div className="col-span-4 my-auto flex min-w-0 items-center justify-center gap-x-2 text-sm text-slate-800">
        {renderSelectedSurveysText(webhook, surveys)}
        {hasRestrictedAttachedSurvey(surveyVisibilityEnabled, webhook.surveyIds, surveys) && (
          <RestrictedSurveyHint kind="paused" />
        )}
      </div>
      <div className="col-span-2 my-auto text-center text-sm text-slate-800">
        {renderSelectedTriggersText(webhook, t)}
      </div>
      <div className="col-span-2 my-auto text-center text-sm whitespace-nowrap text-slate-500">
        {timeSince(webhook.updatedAt.toString(), locale)}
      </div>
      <div className="text-center"></div>
    </div>
  );
};

"use client";

import { WebhookIcon } from "lucide-react";
import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";
import { Webhook } from "@formbricks/database/prisma-browser";
import { TSurvey } from "@formbricks/types/surveys/types";
import { type TUserLocale } from "@formbricks/types/user";
import { WebhookOverviewTab } from "@/modules/integrations/webhooks/components/webhook-overview-tab";
import { WebhookSettingsTab } from "@/modules/integrations/webhooks/components/webhook-settings-tab";
import {
  Dialog,
  DialogBody,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/modules/ui/components/dialog";

interface WebhookModalProps {
  open: boolean;
  setOpen: (v: boolean) => void;
  webhook: Webhook;
  surveys: TSurvey[];
  isReadOnly: boolean;
  allowInternalUrls: boolean;
  surveyVisibilityEnabled: boolean;
}

export const WebhookModal = ({
  open,
  setOpen,
  webhook,
  surveys,
  isReadOnly,
  allowInternalUrls,
  surveyVisibilityEnabled,
}: Readonly<WebhookModalProps>) => {
  const { t, i18n } = useTranslation();
  const locale = (i18n.resolvedLanguage ?? i18n.language ?? "en-US") as TUserLocale;
  const [activeTab, setActiveTab] = useState(0);

  const tabs = [
    {
      title: t("common.overview"),
      children: <WebhookOverviewTab webhook={webhook} surveys={surveys} locale={locale} />,
    },
    {
      title: t("common.settings"),
      children: (
        <WebhookSettingsTab
          webhook={webhook}
          surveys={surveys}
          setOpen={setOpen}
          isReadOnly={isReadOnly}
          allowInternalUrls={allowInternalUrls}
          surveyVisibilityEnabled={surveyVisibilityEnabled}
        />
      ),
    },
  ];

  const webhookName = webhook.name || t("common.webhook"); // NOSONAR // We want to check for empty strings

  const handleTabClick = (index: number) => {
    setActiveTab(index);
  };

  useEffect(() => {
    if (!open) {
      setActiveTab(0);
    }
  }, [open]);

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogContent disableCloseOnOutsideClick>
        <DialogHeader>
          <WebhookIcon />
          <DialogTitle>{webhookName}</DialogTitle> {/* NOSONAR // We want to check for empty strings */}
          <DialogDescription>{webhook.url}</DialogDescription>
        </DialogHeader>
        <DialogBody>
          <div className="flex h-full w-full flex-col">
            <div className="flex w-full items-center justify-center gap-x-2 border-b border-slate-200 px-6">
              {tabs.map((tab, index) => (
                <button
                  key={tab.title}
                  type="button"
                  className={`mr-4 px-1 pb-3 focus:outline-hidden ${
                    activeTab === index
                      ? "border-b-2 border-brand-dark font-semibold text-slate-900"
                      : "text-slate-500 hover:text-slate-700"
                  }`}
                  onClick={() => handleTabClick(index)}>
                  {tab.title}
                </button>
              ))}
            </div>
            <div className="flex-1 overflow-y-auto pt-4">{tabs[activeTab].children}</div>
          </div>
        </DialogBody>
      </DialogContent>
    </Dialog>
  );
};

import { WebhooksPage } from "@/modules/integrations/webhooks/page";
import { getSettingsPageMetadata } from "@/modules/settings/lib/metadata";

export const generateMetadata = () => getSettingsPageMetadata("common.webhooks");

export default WebhooksPage;

"use client";

import clsx from "clsx";
import { CheckIcon, CopyIcon, ExternalLinkIcon, EyeIcon, EyeOff, TrashIcon } from "lucide-react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { useState } from "react";
import { useForm } from "react-hook-form";
import { toast } from "react-hot-toast";
import { useTranslation } from "react-i18next";
import { PipelineTriggers, Webhook } from "@formbricks/database/prisma-browser";
import { TSurvey } from "@formbricks/types/surveys/types";
import { copyToClipboard } from "@/lib/utils/clipboard";
import { getFormattedErrorMessage } from "@/lib/utils/error-message";
import { SurveySelect } from "@/modules/integrations/webhooks/components/survey-select";
import { TriggerCheckboxGroup } from "@/modules/integrations/webhooks/components/trigger-checkbox-group";
import { validWebHookURL } from "@/modules/integrations/webhooks/lib/utils";
import { Button } from "@/modules/ui/components/button";
import { DeleteDialog } from "@/modules/ui/components/delete-dialog";
import { Input } from "@/modules/ui/components/input";
import { Label } from "@/modules/ui/components/label";
import { deleteWebhookAction, testEndpointAction, updateWebhookAction } from "../actions";
import { TWebhookInput } from "../types/webhooks";

interface WebhookSettingsTabProps {
  webhook: Webhook;
  surveys: TSurvey[];
  setOpen: (v: boolean) => void;
  isReadOnly: boolean;
  allowInternalUrls: boolean;
  surveyVisibilityEnabled: boolean;
}

export const WebhookSettingsTab = ({
  webhook,
  surveys,
  setOpen,
  isReadOnly,
  allowInternalUrls,
  surveyVisibilityEnabled,
}: Readonly<WebhookSettingsTabProps>) => {
  const { t } = useTranslation();
  const router = useRouter();
  const { register, handleSubmit } = useForm({
    defaultValues: {
      name: webhook.name,
      url: webhook.url,
      triggers: webhook.triggers,
      surveyIds: webhook.surveyIds,
    },
  });

  const [openDeleteDialog, setOpenDeleteDialog] = useState(false);
  const [isUpdatingWebhook, setIsUpdatingWebhook] = useState(false);
  const [selectedTriggers, setSelectedTriggers] = useState<PipelineTriggers[]>(webhook.triggers);
  const [selectedSurveys, setSelectedSurveys] = useState<string[]>(webhook.surveyIds);
  const [testEndpointInput, setTestEndpointInput] = useState(webhook.url);
  const [endpointAccessible, setEndpointAccessible] = useState<boolean>();
  const [hittingEndpoint, setHittingEndpoint] = useState<boolean>(false);
  const [selectedAllSurveys, setSelectedAllSurveys] = useState(webhook.surveyIds.length === 0);
  const [showSecret, setShowSecret] = useState(false);
  const [copied, setCopied] = useState(false);

  const handleCopySecret = async (text: string) => {
    if (!(await copyToClipboard(text))) {
      toast.error(t("common.failed_to_copy_to_clipboard"));
      return;
    }
    setCopied(true);
    toast.success(t("common.copied_to_clipboard"));
    setTimeout(() => setCopied(false), 2000);
  };

  const handleTestEndpoint = async (sendSuccessToast: boolean): Promise<boolean> => {
    try {
      const { valid, error } = validWebHookURL(testEndpointInput, allowInternalUrls);
      if (!valid) {
        toast.error(error ?? t("common.something_went_wrong_please_try_again"));
        return false;
      }
      setHittingEndpoint(true);
      const testEndpointActionResult = await testEndpointAction({
        url: testEndpointInput,
        webhookId: webhook.id,
        workspaceId: webhook.workspaceId,
      });
      if (!testEndpointActionResult?.data?.success) {
        const errorMessage = getFormattedErrorMessage(testEndpointActionResult);
        throw new Error(errorMessage);
      }
      setHittingEndpoint(false);
      if (sendSuccessToast) toast.success(t("workspace.integrations.webhooks.endpoint_pinged"));
      setEndpointAccessible(true);
      return true;
    } catch (err) {
      setHittingEndpoint(false);
      const errMessage = err instanceof Error ? err.message : "Unknown error occurred";
      toast.error(
        `${t("workspace.integrations.webhooks.endpoint_pinged_error")} \n ${errMessage.length < 250 ? errMessage : t("workspace.integrations.webhooks.please_check_console")}`,
        { className: errMessage.length < 250 ? "break-all" : "" }
      );
      console.error(t("workspace.integrations.webhooks.webhook_test_failed_due_to"), errMessage);
      setEndpointAccessible(false);
      return false;
    }
  };

  const handleSelectAllSurveys = () => {
    setSelectedAllSurveys(!selectedAllSurveys);
    setSelectedSurveys([]);
  };

  const handleCheckboxChange = (selectedValue: PipelineTriggers) => {
    setSelectedTriggers((prevValues) => {
      if (prevValues.includes(selectedValue)) {
        return prevValues.filter((value) => value !== selectedValue);
      } else {
        return [...prevValues, selectedValue];
      }
    });
  };

  const onSubmit = async (data: {
    name: string | null;
    url: string;
    triggers: PipelineTriggers[];
    surveyIds: string[];
  }) => {
    if (selectedTriggers.length === 0) {
      toast.error(t("common.please_select_at_least_one_trigger"));
      return;
    }

    if (!selectedAllSurveys && selectedSurveys.length === 0) {
      toast.error(t("common.please_select_at_least_one_survey"));
      return;
    }

    const endpointHitSuccessfully = await handleTestEndpoint(false);
    if (!endpointHitSuccessfully) {
      return;
    }

    const updatedData: TWebhookInput = {
      name: data.name ?? "",
      url: data.url as string,
      source: webhook.source as TWebhookInput["source"],
      triggers: selectedTriggers,
      surveyIds: selectedSurveys,
    };
    setIsUpdatingWebhook(true);
    const updateWebhookActionResult = await updateWebhookAction({
      webhookId: webhook.id,
      webhookInput: updatedData,
    });
    if (updateWebhookActionResult?.data) {
      router.refresh();
      toast.success(t("workspace.integrations.webhooks.webhook_updated_successfully"));
    } else {
      const errorMessage = getFormattedErrorMessage(updateWebhookActionResult);
      toast.error(errorMessage);
    }
    setIsUpdatingWebhook(false);
    setOpen(false);
  };

  return (
    <div>
      <form className="space-y-4" onSubmit={handleSubmit(onSubmit)}>
        <div className="col-span-1">
          <Label htmlFor="Name">{t("common.name")}</Label>
          <div className="mt-1 flex">
            <Input
              type="text"
              id="name"
              {...register("name")}
              disabled={isReadOnly}
              defaultValue={webhook.name ?? ""}
              placeholder={t("workspace.integrations.webhooks.webhook_name_placeholder")}
            />
          </div>
        </div>

        <div className="col-span-1">
          <Label htmlFor="URL">{t("common.url")}</Label>
          <div className="mt-1 flex">
            <Input
              {...register("url", {
                value: testEndpointInput,
              })}
              type="text"
              value={testEndpointInput}
              onChange={(e) => {
                setTestEndpointInput(e.target.value);
              }}
              readOnly={isReadOnly || webhook.source !== "user"}
              className={clsx(
                isReadOnly || webhook.source !== "user"
                  ? "cursor-not-allowed bg-slate-100 text-slate-500"
                  : null,
                endpointAccessible === true
                  ? "border-green-500 bg-green-50"
                  : endpointAccessible === false
                    ? "border-red-200 bg-red-50"
                    : endpointAccessible === undefined
                      ? "border-slate-200 bg-white"
                      : null
              )}
              placeholder={t("workspace.integrations.webhooks.webhook_url_placeholder")}
            />
            {!isReadOnly && (
              <Button
                type="button"
                variant="secondary"
                loading={hittingEndpoint}
                className="ml-2 whitespace-nowrap"
                onClick={() => {
                  handleTestEndpoint(true);
                }}>
                {t("workspace.integrations.webhooks.test_endpoint")}
              </Button>
            )}
          </div>
        </div>

        {webhook.secret && (
          <div className="col-span-1">
            <Label htmlFor="secret">{t("workspace.integrations.webhooks.signing_secret")}</Label>
            <div className="mt-1 flex">
              <div className="relative flex-1">
                <Input
                  type={showSecret ? "text" : "password"}
                  id="secret"
                  readOnly
                  value={webhook.secret}
                  className="pr-10 font-mono text-sm"
                />
                <button
                  type="button"
                  className="absolute top-1/2 right-3 -translate-y-1/2 transform"
                  onClick={() => setShowSecret(!showSecret)}>
                  {showSecret ? (
                    <EyeOff className="size-5 text-slate-400" />
                  ) : (
                    <EyeIcon className="size-5 text-slate-400" />
                  )}
                </button>
              </div>
              <Button
                type="button"
                variant="secondary"
                className="ml-2 whitespace-nowrap"
                onClick={() => handleCopySecret(webhook.secret ?? "")}>
                {copied ? (
                  <>
                    <CheckIcon className="size-4" />
                    {t("common.copied")}
                  </>
                ) : (
                  <>
                    <CopyIcon className="size-4" />
                    {t("common.copy")}
                  </>
                )}
              </Button>
            </div>
            <p className="mt-1 text-xs text-slate-500">
              {t("workspace.integrations.webhooks.secret_description")}
            </p>
            <Link
              href="https://formbricks.com/docs/platform/features/integrations/webhooks#webhook-security-with-standard-webhooks"
              target="_blank"
              className="mt-1 inline-flex items-center gap-1 text-xs text-slate-600 underline hover:text-slate-800">
              {t("workspace.integrations.webhooks.learn_to_verify")}
              <ExternalLinkIcon className="size-3" />
            </Link>
          </div>
        )}

        <div>
          <Label htmlFor="Triggers">{t("workspace.integrations.webhooks.triggers")}</Label>
          <TriggerCheckboxGroup
            selectedTriggers={selectedTriggers}
            onCheckboxChange={handleCheckboxChange}
            allowChanges={webhook.source === "user" && !isReadOnly}
          />
        </div>

        <div>
          <Label htmlFor="Surveys">{t("common.surveys")}</Label>
          <SurveySelect
            surveys={surveys}
            selectedSurveys={selectedSurveys}
            selectedAllSurveys={selectedAllSurveys}
            onSelectAllSurveys={handleSelectAllSurveys}
            onSelectedSurveysChange={setSelectedSurveys}
            allowChanges={webhook.source === "user" && !isReadOnly}
            surveyVisibilityEnabled={surveyVisibilityEnabled}
            attachedSurveyIds={webhook.surveyIds}
          />
        </div>

        <div className="flex justify-between gap-x-2">
          <div className="flex gap-x-2">
            {!isReadOnly && (
              <Button type="button" variant="destructive" onClick={() => setOpenDeleteDialog(true)}>
                <TrashIcon />
                {t("common.delete")}
              </Button>
            )}

            <Button variant="secondary" asChild>
              <Link
                href="https://formbricks.com/docs/platform/features/integrations/webhooks"
                target="_blank">
                {t("common.read_docs")}
              </Link>
            </Button>
          </div>

          {!isReadOnly && (
            <div className="flex gap-x-2">
              <Button type="submit" loading={isUpdatingWebhook}>
                {t("common.save_changes")}
              </Button>
            </div>
          )}
        </div>
      </form>
      <DeleteDialog
        open={openDeleteDialog}
        setOpen={setOpenDeleteDialog}
        deleteWhat={t("common.webhook")}
        text={t("workspace.integrations.webhooks.webhook_delete_confirmation")}
        onDelete={async () => {
          setOpen(false);
          const deleteWebhookActionResult = await deleteWebhookAction({ id: webhook.id });
          if (deleteWebhookActionResult?.data) {
            router.refresh();
            toast.success(t("workspace.integrations.webhooks.webhook_deleted_successfully"));
          } else {
            const errorMessage = getFormattedErrorMessage(deleteWebhookActionResult);
            toast.error(errorMessage);
          }
        }}
      />
    </div>
  );
};

import { DANGEROUSLY_ALLOW_WEBHOOK_INTERNAL_URLS } from "@/lib/constants";
import { getTranslate } from "@/lingodotdev/server";
import { AddWebhookButton } from "@/modules/integrations/webhooks/components/add-webhook-button";
import { WebhookRowData } from "@/modules/integrations/webhooks/components/webhook-row-data";
import { WebhookTable } from "@/modules/integrations/webhooks/components/webhook-table";
import { WebhookTableHeading } from "@/modules/integrations/webhooks/components/webhook-table-heading";
import { getWebhookSurveys } from "@/modules/integrations/webhooks/lib/surveys";
import { getWebhooks } from "@/modules/integrations/webhooks/lib/webhook";
import { isSurveyVisibilityEnforced } from "@/modules/survey/visibility/lib/gate";
import { GoBackButton } from "@/modules/ui/components/go-back-button";
import { PageContentWrapper } from "@/modules/ui/components/page-content-wrapper";
import { PageHeader } from "@/modules/ui/components/page-header";
import { getWorkspaceAuth } from "@/modules/workspaces/lib/utils";

export const WebhooksPage = async (props: { params: Promise<{ workspaceId: string }> }) => {
  const params = await props.params;
  const t = await getTranslate();

  const { isReadOnly, organization, session, workspace } = await getWorkspaceAuth(params.workspaceId);

  const [webhooks, surveys, surveyVisibilityEnabled] = await Promise.all([
    getWebhooks(workspace.id),
    getWebhookSurveys(workspace.id, session.user.id, organization.id),
    isSurveyVisibilityEnforced(),
  ]);

  const renderAddWebhookButton = () => (
    <AddWebhookButton
      workspaceId={workspace.id}
      surveys={surveys}
      allowInternalUrls={DANGEROUSLY_ALLOW_WEBHOOK_INTERNAL_URLS}
      surveyVisibilityEnabled={surveyVisibilityEnabled}
    />
  );

  return (
    <PageContentWrapper>
      <GoBackButton />
      <PageHeader pageTitle={t("common.webhooks")} cta={!isReadOnly ? renderAddWebhookButton() : <></>} />
      <WebhookTable
        workspaceId={workspace.id}
        webhooks={webhooks}
        surveys={surveys}
        isReadOnly={isReadOnly}
